  // Two 16-byte cp.asyncs per operand per thread per stage (fully coalesced).
  auto load_tile = [&](int kt, int buf) {
    #pragma unroll
    for (int p = 0; p < 2; ++p) {
      int idx = tid + p * 256;
      int row = idx >> 2;          // 128 rows of the A tile
      int kc  = (idx & 3) * 4;     // 4 x float4 per row
      const float* g = A + (long long)(m0 + row) * K + kt * BK + kc;
      __pipeline_memcpy_async(&smemA_base[buf * A_STAGE + row * SA_LD + kc], g, 16);
    }
    #pragma unroll
    for (int p = 0; p < 2; ++p) {
      int idx = tid + p * 256;
      int kk = idx >> 5;           // 16 k-rows of the B tile
      int nn = (idx & 31) * 4;     // 32 x float4 per row
      const float* g = B + (long long)(kt * BK + kk) * N + n0 + nn;
      __pipeline_memcpy_async(&smemB_base[buf * B_STAGE + kk * SB_LD + nn], g, 16);
    }
  };
  // 32x64 warp tile held as a 2x4 grid of 16x16x8 TF32 WMMA accumulators.
  nvcuda::wmma::fragment<nvcuda::wmma::accumulator, 16, 16, 8, float> acc[2][4];
  #pragma unroll
