  auto dA = make_stride(K, Int<1>{});       // A[M,K] row-major as (M,K)
  auto dB = make_stride(Int<1>{}, N);       // B[K,N] row-major viewed as (N,K)
  auto dC = make_stride(N, Int<1>{});       // C[M,N] row-major
  auto shape_MNK = make_shape(M, N, K);

